package com.medicarepro;
import java.security.*; import java.sql.*; import java.util.*; import javax.crypto.SecretKeyFactory; import javax.crypto.spec.PBEKeySpec;
public final class AuthService {
 public record User(long id,String username,String name,String role){public boolean headDoctor(){return "HEAD_DOCTOR".equals(role);}}
 private final Database db; private final SecureRandom random=new SecureRandom(); public AuthService(Database db){this.db=db;}
 public User login(String username,char[] password)throws Exception{try(Connection c=db.connect();PreparedStatement s=c.prepareStatement("SELECT id,username,display_name,role,password_hash,password_salt FROM users WHERE username=? AND active=1")){s.setString(1,username.trim().toLowerCase(Locale.ROOT));try(ResultSet r=s.executeQuery()){if(!r.next()||!verify(password,r.getBytes(5),r.getBytes(6)))return null;return new User(r.getLong(1),r.getString(2),r.getString(3),r.getString(4));}}}
 public boolean hasHeadDoctor()throws SQLException{try(Connection c=db.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM users WHERE role='HEAD_DOCTOR'")){return r.next()&&r.getInt(1)>0;}}
 public void createHeadDoctor(String u,String n,char[] p)throws Exception{create(u,n,p,"HEAD_DOCTOR");} public void createUser(User a,String u,String n,char[] p)throws Exception{if(a==null||!a.headDoctor())throw new SecurityException("Only the Head Doctor can manage accounts.");create(u,n,p,"USER");}
 private void create(String u,String n,char[] p,String role)throws Exception{if(u==null||!u.trim().matches("[a-zA-Z0-9._-]{3,50}"))throw new IllegalArgumentException("Username must be 3-50 letters, numbers, dot, underscore, or hyphen.");if(n==null||n.isBlank())throw new IllegalArgumentException("Display name is required.");if(p==null||p.length<8)throw new IllegalArgumentException("Password must contain at least 8 characters.");byte[] salt=new byte[16];random.nextBytes(salt);try(Connection c=db.connect();PreparedStatement s=c.prepareStatement("INSERT INTO users(username,display_name,password_hash,password_salt,role) VALUES(?,?,?,?,?)")){s.setString(1,u.trim().toLowerCase(Locale.ROOT));s.setString(2,n.trim());s.setBytes(3,hash(p,salt));s.setBytes(4,salt);s.setString(5,role);s.executeUpdate();}catch(SQLException e){if(e.getMessage().contains("UNIQUE"))throw new IllegalArgumentException("That username already exists.");throw e;}}
 private byte[] hash(char[] p,byte[] salt)throws Exception{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(p,salt,120000,256)).getEncoded();} private boolean verify(char[] p,byte[] h,byte[] s)throws Exception{return MessageDigest.isEqual(h,hash(p,s));}
}
